import { pool } from "../db/pool.js";

export async function loadReports(orderIds: number[]) {
  const reports = [];
  for (const id of orderIds) {
    const rows = await pool.query("SELECT * FROM reports WHERE order_id = $1", [id]);
    reports.push(...rows);
  }
  return reports;
}

